function hideAll(){['cover','guide','nameEntry','preSurvey','postSurvey','chapters','prologue','flyer','explore','dialogue','phone','bag','document','clueDetail','notebook','ending','endingTwo','planner','result','thanks'].forEach(id=>$('#'+id)?.classList.add('hidden'));$('#bagBtn').classList.add('hidden');$('#sceneNext').classList.add('hidden');$('#sceneNext').classList.remove('primary-center')}
function updateChapterButtons(){[['dayOne',1],['dayTwo',2],['dayThree',3]].forEach(([id,day])=>{const b=$('#'+id),open=state.unlockedDay>=day;b.disabled=!open;b.querySelector('span').textContent=open?'開始':'🔒'})}
function unlockDay(day){state.unlockedDay=Math.max(state.unlockedDay,day);localStorage.setItem('clockUnlockedDay',state.unlockedDay);updateChapterButtons()}
function page(id){hideAll();$('#hud').classList.add('hidden');$('#'+id).classList.remove('hidden');if(id==='chapters')updateChapterButtons();if(id==='nameEntry'){$('#playerName').value=state.playerName;setTimeout(()=>$('#playerName').focus(),80)}if(id==='preSurvey'){photo.style.backgroundImage='url("prologue-chat.webp")';track('pretest_opened')}if(id==='postSurvey'){photo.style.backgroundImage='url("day3-group-photo-consistent.webp")';track('posttest_opened')}if(id==='cover')photo.style.backgroundImage='url("hexing-campus.webp")';if(id==='prologue')photo.style.backgroundImage='url("prologue-chat.webp")'}
$$('[data-go]').forEach(b=>b.onclick=()=>page(b.dataset.go));
function say(lines,done){dialogue.classList.remove('hidden');let i=0;const show=()=>{const x=lines[i];if(x.img)photo.style.backgroundImage=`url("${x.img}")`;speaker.textContent=x.s==='你'?(state.playerName||'你'):(x.s||'');line.textContent=x.t;choices.innerHTML='';prevLine.classList.toggle('hidden',i===0);prevLine.onclick=()=>{if(i>0){i--;show()}};next.classList.remove('hidden');next.textContent=i===lines.length-1?'繼續':'下一句';next.onclick=()=>{if(++i<lines.length)show();else{dialogue.classList.add('hidden');prevLine.classList.add('hidden');done&&done()}}};show()}
function choose(text,opts,done){dialogue.classList.remove('hidden');speaker.textContent='';line.textContent=text;prevLine.classList.add('hidden');next.classList.add('hidden');choices.innerHTML='';opts.forEach(o=>{const b=document.createElement('button');b.textContent=o.label;b.onclick=()=>{choices.innerHTML='';dialogue.classList.add('hidden');done(o.value)};choices.append(b)})}
function resetSceneHistory(){sceneHistory.length=0;sceneHistoryIndex=-1}
function updateSceneNav(){const forward=$('#sceneForward');forward.classList.toggle('hidden',sceneHistoryIndex>=sceneHistory.length-1)}
function showScene(key,track=true){if(track){if(sceneHistory[sceneHistoryIndex]!==key){sceneHistory.splice(sceneHistoryIndex+1);sceneHistory.push(key);sceneHistoryIndex=sceneHistory.length-1}}state.phase=key;if(sceneCheckpoints[key])markCheckpoint(sceneCheckpoints[key]);const s=scenes[key];hideAll();$('#hud').classList.remove('hidden');$('#explore').classList.remove('hidden');$('#hudDay').textContent=`DAY ${state.day}`;updateSceneNav();if(key==='campus')$('#bagBtn').classList.remove('hidden');if(key==='rear'&&['door','crumbs','prints'].every(k=>state.clues.has(k))&&!state.reported){$('#sceneNext').textContent='三處都看完了，和艾莉整理';$('#sceneNext').classList.add('primary-center');$('#sceneNext').classList.remove('hidden')}if(key==='compare'&&state.clay.has('photoPrint')&&state.clay.has('phoneShot')){$('#sceneNext').textContent='完成腳印比對';$('#sceneNext').classList.remove('hidden')}const freeNext={team:'結束自由互動，前往大下課',day2map:'前往下一關',day2tree:'完成校園探索',day2plantkids:'繼續植物調查'};if(freeNext[key]){$('#sceneNext').textContent=freeNext[key];$('#sceneNext').classList.remove('hidden')}$('#place').textContent=s.place;photo.style.backgroundImage=`url("${s.img}")`;const box=$('#spots');box.innerHTML='';s.spots.forEach(([id,x,y,w,h,title,text,type])=>{const b=document.createElement('button');b.className='spot';b.dataset.spot=id;b.setAttribute('aria-label',title);Object.assign(b.style,{left:x+'%',top:y+'%',width:w+'%',height:h+'%'});b.onclick=()=>tap(id,title,text,type);box.append(b)});$('#explore .tap-help')?.remove();$('#explore .evidence-inset')?.remove();if(key==='day2plants'){const e=document.createElement('div');e.className='evidence-inset';e.innerHTML='<small>早上拍下的照片</small>';$('#explore').append(e)}refreshSceneHint(key)}
function cameraSnap(){const f=$('#cameraFlash');f.classList.remove('snap');void f.offsetWidth;f.classList.add('snap');setTimeout(()=>f.classList.remove('snap'),450)}
function refreshSceneHint(key){
 const old=$('#explore .tap-help');if(old)old.remove();
 const rearFound=['door','crumbs','prints'].filter(k=>state.clues.has(k)).length;
 const compared=state.clay.has('photoPrint')&&state.clay.has('phoneShot');
 let hint='';
 if(key==='campus')hint=state.briefRead?'沿著走廊找找後棟入口。':'背包裡的手機正在震動，打開背包查看。';
 else if(key==='rear')hint=`原本這裡門緊鎖、乾乾淨淨。找出空間中三個不尋常的地方（${rearFound}/3）`;
 else if(key==='team')hint='可以自由和孩子互動；準備好後，點「前往大下課」。';
 else if(key==='search'&&!state.clues.has('laian'))hint='找找賴安在哪裡';
 else if(key==='compare'&&!compared)hint='請比對兩張照片';
 else if(key==='dismissal')hint='點擊落在隊伍最後的孩子';
 else if(key==='day2rear'&&!state.d2clues.has('d2foot'))hint='點擊花圃裡的新腳印，拍下線索';
 else if(key==='day2map')hint='可以和每個孩子聊聊；準備好後，點「前往下一關」。';
 else if(key==='day2tree')hint='看看孩子們怎麼解題；準備好後，點「完成校園探索」。';
 else if(key==='day2drawing'&&!state.d2clues.has('d2drawing'))hint='點擊正在畫畫的芮琪';
 else if(key==='day2drawingReveal'&&!state.d2clues.has('d2drawing'))hint='圈出畫裡和現在小隊對不上的地方';
 else if(key==='day2plantkids')hint='聽聽孩子們的發現；準備好後，點「繼續植物調查」。';
 else if(key==='day2plants'&&!state.d2clues.has('d2plant'))hint='點選最符合早上照片線索的植物';
 else if(key==='day2board'&&!state.d2clues.has('d2board'))hint='連恩好像注意到什麼，點擊他查看';
 else if(key==='day2alan'&&!state.d2clues.has('d2alan'))hint='灌木附近有人影，找出躲在後棟小路的孩子';
 if(hint){const h=document.createElement('div');h.className='tap-help';h.textContent=hint;$('#explore').append(h)}
}
function tap(id,title,text,type){
 if(type==='rear'){if(!state.briefRead)return toast('手機還在背包裡震動。');showScene('rear');if(!state.rearIntroSeen){state.rearIntroSeen=true;say([{s:'艾莉',t:'這裡很久沒用了，怎麼感覺有人來過？'},{s:'你',t:'先別搬桌椅。畫面有三個異常：側門、牆邊地面和左下方腳印，分別點開看看。'}],()=>showScene('rear'))}return}
 if(type==='clue'){const first=!state.clues.has(id);state.clues.add(id);if(first){updateCount();track('clue_found',{day:1,clue:id})}hideAll();$('#clueDetail').classList.remove('hidden');$('#clueTitle').textContent=title;$('#clueText').innerHTML=`<p>${text}</p>`;return}
 if(type==='child'){openChild(id,text);return}
 if(type==='return'){state.clues.add('laian');updateCount();photo.style.backgroundImage='url("laian-return.webp")';say([{s:'你',t:'賴安！你去哪裡了？',img:'laian-return.webp'},{s:'賴安',t:'……我去後棟看獨角仙。',img:'laian-return.webp'},{s:'你',t:'下次不可以擅自離隊，聽到沒有？'},{s:'賴安',t:'知道了……'},{t:'下午黏土課，你想起後棟腳印，趁賴安伸腳時拍下鞋底。',img:'laian-shoe-sole.webp'},{s:'艾莉',t:'把它和早上的腳印比比看。'},{t:'你回到後棟補拍腳印，準備比對兩張照片。',img:'footprint-photo.webp'}],()=>showScene('compare'));return}
 if(type==='compare'){state.clay.add(id);const evidenceImg=id==='phoneShot'?'laian-shoe-sole.webp':'footprint-photo.webp';say([{s:title,t:text,img:evidenceImg}],()=>showScene('compare'));return}
 if(type==='d2foot'){state.d2clues.add('d2foot');updateCount();say([{t:'你蹲下查看。新的腳印停在門外，完全沒有跨過上鎖的側門。',img:'day2-rear-v2.webp'},{s:'艾莉',t:'所以他今天沒有從門進去。你看，泥痕往花圃那邊偏了。'},{s:'你',t:'圍牆底下有個很小的裂口……不是正常出入口，但小孩可能勉強擠得過去。'},{t:'你拿出手機，讓腳印、泥痕和旁邊幾顆細長的黑色種子一起進入取景框。',img:'day2-footprint-camera.webp'}],()=>{cameraSnap();setTimeout(()=>say([{t:'喀擦。照片定格在相簿裡。'},{t:'08:20，孩子到齊後，第二天的校園大探索闖關開始。',img:'day2-explore-map-v2.webp'}],()=>showScene('day2map')),460)});return}
 if(type==='d2map'){state.d2talk.add(id);const scripts={mapLaian:[{s:'賴安',t:'先確認位置再走，今天不會再走錯。'},{s:'你',t:'好，你負責看方向。'}],mapLien:[{s:'連恩',t:'大家靠過來，我把地圖轉成同一個方向。'},{s:'你',t:'很好，別讓隊伍分散。'}],mapLuoqi:[{s:'洛祈',t:'我到第一個樓梯平台探路，可以嗎？'},{s:'你',t:'可以，但要讓大家看得到你。'}],mapRiqi:[{s:'芮琪',t:'補習班做過類似的地圖題，媽媽昨晚也陪我先看過路線。'},{s:'你',t:'難怪妳這麼快找到方向。'}]};say(scripts[id].map((x,i)=>i?x:{...x,img:'day2-explore-map-v2.webp'}),()=>showScene('day2map'));return}
 if(type==='d2tree'){state.d2talk.add(id);const scripts={treeLaian:[{s:'賴安',t:'卡片先放答案袋，才不會弄丟。'},{s:'你',t:'好，最後記得一起確認答案。'}],treeLien:[{s:'連恩',t:'洛祈找到卡片了！大家一起來看。'},{s:'你',t:'你很會把隊伍叫回來。'}],treeLuoqi:[{s:'洛祈',t:'大家都看高處，我看樹根，真的找到了！'},{s:'你',t:'這個想法很有用。'}],treeRiqi:[{s:'芮琪',t:'我把每一關的發現分開記，等等比較不會忘。'},{s:'你',t:'安靜記錄也是重要的工作。'}]};say(scripts[id].map((x,i)=>i?x:{...x,img:'day2-explore-tree-v2.webp'}),()=>showScene('day2tree'));return}
 if(type==='plantKid'){state.d2talk.add(id);const scripts={plantKidLaian:[{s:'賴安',t:'這個果實是圓的，照片裡的種子是一根一根。'},{s:'你',t:'好，先排除這一種。'}],plantKidLien:[{s:'連恩',t:'這片葉子像愛心，我先記住位置。'},{s:'你',t:'可以，但還要比對種子。'}],plantKidLuoqi:[{s:'洛祈',t:'我可以翻開葉子找嗎？'},{s:'艾莉',t:'從旁邊看就好，不碰不認識的植物。'}],plantKidRiqi:[{s:'芮琪',t:'我把三個位置和種子形狀都畫下來了。'},{s:'你',t:'等等就照妳的紀錄比對。'}]};say(scripts[id].map((x,i)=>i?x:{...x,img:'day2-plant-kids-v2.webp'}),()=>showScene('day2plantkids'));return}
 if(type==='d2drawing'){drawingPuzzle();return}
 if(type==='drawingWrong'){toast('這個人看起來是現在小隊裡的成員。再看看其他地方。');return}
 if(type==='drawingRight'){state.d2clues.add('d2drawing');updateCount();say([{s:'你',t:'這個背書包的男孩是誰？我們這一隊現在不是只有四個人嗎？',img:'day2-richi-reveal-consistent.webp'},{s:'芮琪',t:'因為以前不是只有四個。還有一個人常常跟我們一起玩。'},{s:'你',t:'那他後來怎麼沒有再跟你們一起參加了？'},{t:'芮琪低頭摸了摸紙張邊緣，沒有回答，只把畫本輕輕闔上。'},{t:'13:20，下午的植物大調查開始。四個孩子拿著紀錄板走在前面，分頭觀察步道兩旁的植物。',img:'day2-plant-kids-v2.webp'}],()=>showScene('day2plantkids'));return}
 if(type==='plantWrong'){say([{s:title,t:text,img:'day2-plant-puzzle-consistent.webp'},{s:'艾莉',t:'形狀不太一樣。再看看照片裡那種細長、會黏住衣服的種子。'}],()=>showScene('day2plants'));return}
 if(type==='plantRight'){state.d2clues.add('d2plant');updateCount();say([{s:'你',t:'找到了。這些咸豐草的黑色針狀種子，和腳印旁的一模一樣。',img:'day2-plant-puzzle-consistent.webp'},{s:'艾莉',t:'而且它只集中在舊候車亭和後棟外側這一帶。留下腳印的人，是從這條路過來的。'},{t:'15:10，大家回教室布置成果展看板。連恩貼到一半，忽然望向後棟。',img:'day2-board.webp'}],()=>showScene('day2board'));return}
 if(type==='d2board'){state.d2clues.add('d2board');say([{t:'連恩把最後一張植物照片貼上看板，手卻忽然停在半空中。他越過窗戶，往後棟方向看了好幾秒。',img:'day2-board.webp'},{s:'你',t:'連恩，你在看什麼？'},{s:'連恩',t:'沒有啊……我只是看外面。'},{t:'你順著他的視線望去，正好是舊候車亭小路通往後棟的方向。早上的腳印、芮琪畫裡的第五個人，慢慢在腦中連了起來。'},{s:'你',t:'艾莉，妳先陪大家把看板貼完。我去後棟確認一下，很快回來。'},{s:'艾莉',t:'好，有狀況就馬上叫我。'},{t:'你沿著連恩剛才的視線走進後棟小路。樹影和灌木之間，似乎有個很小的人影。',img:'day2-alan-hidden.webp'}],()=>showScene('day2alan'));return}
 if(type==='d2alan'){state.d2clues.add('d2alan');updateCount();alanConversation();return}
 if(type==='dismiss'){say([{t:'洛祈落在隊伍最後，望著後棟的方向站了幾秒。'},{s:'你',t:'洛祈，跟上囉！'},{t:'他像是突然回神，抓緊背包跑回隊伍。'},{s:'艾莉',t:'他剛剛在看什麼？'},{s:'你',t:'不知道。可能只是又在放空吧。'},{t:'你卻再次想起那串不屬於賴安的腳印。後棟附近，可能還有另一個人來過。'}],()=>{completeDay(1);unlockDay(2);page('ending')});return}
 say([{s:title,t:text}],()=>showScene(state.phase))
}
function openChild(id,img){const d=childScripts[id];hideAll();$('#hud').classList.remove('hidden');$('#place').textContent=d.name;photo.style.backgroundImage=`url("${img}")`;say(d.intro,()=>choose(d.question,d.opts,v=>{track('child_choice',{day:1,child:id,choice:v});say(d.answers[v],()=>{state.children.add(id);showScene('team')})}))}
function teamArrival(){hideAll();$('#hud').classList.remove('hidden');$('#place').textContent='08:00・第三小隊報到';photo.style.backgroundImage='url("team-arrival.webp")';say([{t:'08:00，第三小隊的四個孩子到齊，依序自我介紹。',img:'team-arrival.webp'},{s:'賴安',t:'我是五年級賴安，喜歡自然課和找小動物，也可以幫忙發材料。',img:'laian-intro.webp'},{s:'連恩',t:'我是五年級連恩，喜歡打球、聊天和認識新朋友。',img:'lien-intro.webp'},{s:'洛祈',t:'我是四年級洛祈，喜歡體育課，也喜歡到處找好玩的東西。',img:'luoqi-intro.webp'},{s:'芮琪',t:'我是五年級芮琪，喜歡畫畫和整理東西，也有多帶文具。',img:'richi-intro.webp'},{s:'艾莉',t:'接下來三天，請大家多多指教。',img:'team-arrival.webp'},{t:'破冰結束後，上午的自我介紹小卡課開始。',img:'team-classroom.webp'}],()=>showScene('team'))}
function afterChildren(){say([{s:'艾莉',t:'四個孩子個性差好多。芮琪準備得最完整，看起來最不用操心。',img:'team-classroom.webp'},{t:'10:30，大下課。賴安說這層廁所都有人，急著問能不能下樓。',img:'restroom-full.webp'},{s:'你',t:'可以，快去快回，不要亂跑！'},{t:'五分鐘後，賴安仍沒回來。你急忙下樓找人。',img:'restroom-search.webp'},{t:'樓下廁所沒有人回應，你只好一路找到後棟。'}],()=>showScene('search'))}
function concernReport(){hideAll();$('#hud').classList.remove('hidden');say([{s:'艾莉',t:'昨天門是我們親手鎖的。現在門開著，裡面又有零食碎屑和小孩子大小的腳印。'},{s:'你',t:'如果有人能隨便進來，營隊開始後孩子跑到後棟會很危險。'},{s:'艾莉',t:'先拍下來回報主任，請學校確認門鎖和出入紀錄。'}],()=>openPhone('report'))}
function openBag(){hideAll();const bag=$('#bag');bag.style.backgroundImage='url("open-backpack-map.webp")';bag.classList.remove('hidden')}
function openDocument(kind,source='bag'){state.docSource=source;hideAll();$('#document').classList.remove('hidden');if(kind==='schedule'){$('#docType').textContent='備忘錄';$('#docTitle').textContent='三日營隊行程';$('#docBody').innerHTML='<div class="schedule-grid"><div class="schedule-day"><b>第一天｜認識彼此</b><p>08:00 開營與破冰</p><p>09:30 自我介紹小卡</p><p>13:40 創意黏土工坊</p><p>15:00 賦歸</p></div><div class="schedule-day"><b>第二天｜校園探索</b><p>08:20 校園闖關</p><p>09:50 自然拓印</p><p>13:40 植物觀察</p><p>15:10 成果展看板</p></div><div class="schedule-day"><b>第三天｜成果與告別</b><p>08:20 回憶紀念冊</p><p>09:50 全員總決戰</p><p>11:00 成果發表</p><p>13:00 結業式</p></div></div>'}else{$('#docType').textContent='學校提供資料';$('#docTitle').textContent='合興國小場地圖';$('#docBody').innerHTML='<div class="map-card"><div class="map-block map-front">校門／穿堂<br>前棟教室</div><div class="map-block map-field">操場與老榕樹</div><div class="map-path"></div><div class="map-block map-rear">後棟<br>側門／舊教室</div></div>'}}
function openPhone(mode='brief'){state.phoneMode=mode;state.phoneView='home';hideAll();$('#phone').classList.remove('hidden');renderPhoneHome()}
function renderPhoneHome(){state.phoneView='home';$('#phoneTitle').textContent='';const guide=state.phoneMode==='report'?'<div class="phone-guide">請開啟 LINE，回報給營隊主任</div>':'';$('#messages').innerHTML=guide+'<div class="phone-home"><div class="phone-clock"><small>8月18日　星期二</small><b>07:32</b></div><div class="phone-apps"><button id="lineApp"><i class="app-icon">LINE</i><span>LINE</span></button><button id="notesApp"><i class="app-icon notes-icon">備忘錄</i><span>備忘錄</span></button><button id="cameraApp"><i class="app-icon camera-icon">相機</i><span>相機</span></button></div></div>';$('#lineApp').onclick=renderContacts;$('#notesApp').onclick=()=>openDocument('schedule','phone');$('#cameraApp').onclick=()=>toast('目前沒有需要拍攝的東西。')}
function renderContacts(){state.phoneView='list';$('#phoneTitle').textContent='LINE';const unread=state.briefRead?'':'<span class="unread">1</span>',guide=state.phoneMode==='report'?'<div class="phone-guide">請點擊「營隊主任」回報後棟狀況</div>':'';$('#messages').innerHTML=guide+`<div class="chat-list"><button class="chat-row" id="directorChat"><span class="avatar">主任</span><span><b>營隊主任</b><small>${state.phoneMode==='report'?'桌椅找到了嗎？':'你們到學校了嗎？'}</small></span>${unread}</button><button class="chat-row" id="allyChat"><span class="avatar">艾莉</span><span><b>艾莉</b><small>我在穿堂這邊～</small></span></button></div>`;$('#directorChat').onclick=renderDirector;$('#allyChat').onclick=()=>toast('艾莉就在你旁邊。')}
function renderDirector(){state.phoneView='chat';$('#phoneTitle').textContent='營隊主任';const m=$('#messages');if(state.phoneMode==='report'){m.innerHTML='<div class="msg"><div class="avatar">主任</div><div class="bubble">桌椅找到了嗎？</div></div>';const b=document.createElement('button');b.className='send-report';b.textContent='拍照並回報後棟狀況';b.onclick=sendReport;m.append(b);return}m.innerHTML='<div class="msg"><div class="avatar">主任</div><div class="bubble">你們到學校了嗎？</div></div>';if(!state.briefRead){const b=document.createElement('button');b.className='send-report';b.textContent='回覆：到了！';b.onclick=sendArrival;m.append(b)}else m.innerHTML+='<div class="msg me"><div class="bubble">到了！</div></div><div class="msg"><div class="avatar">主任</div><div class="bubble">昨天你們反映桌椅不夠，可以去後棟搬喔。</div></div><div class="msg"><div class="avatar">主任</div><div class="bubble">後棟很久沒用了，所以平常鎖著；你們可以用昨天拿到的側門鑰匙進去搬。</div></div><div class="msg"><div class="avatar">主任</div><div class="bubble">桌椅在右邊第一間教室，搬完記得把側門鎖好。</div></div>'}
function sendArrival(){const m=$('#messages');m.innerHTML='<div class="msg"><div class="avatar">主任</div><div class="bubble">你們到學校了嗎？</div></div><div class="msg me"><div class="bubble">到了！</div></div>';const replies=['昨天你們反映桌椅不夠，可以去後棟搬喔。','後棟很久沒用了，所以平常鎖著；你們可以用昨天拿到的側門鑰匙進去搬。','桌椅在右邊第一間教室，搬完記得把側門鎖好。'];let i=0;const add=()=>{if(i===replies.length){state.briefRead=true;const b=document.createElement('button');b.className='send-report';b.textContent='收起手機';b.onclick=()=>{hideAll();say([{s:'艾莉',t:'訊息看到了？那我們先去搬桌椅。'}],()=>showScene('campus'))};m.append(b);return}setTimeout(()=>{m.innerHTML+=`<div class="msg"><div class="avatar">主任</div><div class="bubble">${replies[i++]}</div></div>`;m.scrollTop=m.scrollHeight;add()},430)};add()}
function sendReport(){state.reported=true;const m=$('#messages');m.innerHTML+=`<div class="msg me"><div class="bubble">主任，後棟側門沒有鎖緊，裡面有小孩子大小的腳印和零食包裝碎屑。我們昨天離開時有確實鎖門。</div></div>`;const replies=['我先查一下鑰匙登記。照紀錄，除了你們，應該只有總務有備份。','我會立刻請總務確認門鎖。營隊期間先不要讓孩子靠近後棟。','你們先把桌椅搬回來，等等孩子就要報到了。'];let i=0;const add=()=>{if(i===replies.length){const b=document.createElement('button');b.className='send-report';b.textContent='收起手機';b.onclick=()=>{hideAll();say([{s:'艾莉',t:'至少學校會處理門鎖。先把桌椅搬走，等等也要注意孩子別往這裡跑。'}],teamArrival)};m.append(b);return}setTimeout(()=>{m.innerHTML+=`<div class="msg"><div class="avatar">主任</div><div class="bubble">${replies[i++]}</div></div>`;m.scrollTop=m.scrollHeight;add()},450)};add()}
function shoePuzzle(){choose('你已經看過兩張照片。哪個判斷最合理？',[{label:'賴安去過後棟，所以腳印一定是他的',value:'wrong1'},{label:'鞋底紋路不同，早上的腳印不是賴安留下的',value:'right'},{label:'只要鞋子大小接近，就能確定是他',value:'wrong2'}],v=>{track('shoe_conclusion',{choice:v});if(v!=='right'){toast('再比對一次兩張照片的鞋底紋路。');setTimeout(shoePuzzle,850);return}state.clues.add('shoes');updateCount();say([{s:'艾莉',t:'賴安的鞋底是水平橫紋，後棟泥腳印卻是鋸齒格狀。不是他的。'},{s:'你',t:'所以他雖然去了後棟，卻不是早上留下腳印的人。'},{s:'艾莉',t:'那他為什麼要騙我們說去廁所？'}],revealTruth)})}
function revealTruth(){say([{t:'回到教室收拾黏土工具時，賴安低著頭捲保鮮膜，忽然小聲叫住你。',img:'clay-cleanup-laian.webp'},{s:'賴安',t:'隊輔老師，你不會跟我媽講喔？'},{s:'你',t:'你是說剛才跑去後棟的事？'},{s:'賴安',t:'我真的只是去看獨角仙，沒有去弄那扇門。'},{s:'你',t:'那你為什麼一開始不直接說？'},{s:'賴安',t:'我怕你覺得我很幼稚，都五年級了還在追蟲。'},{s:'你',t:'喜歡獨角仙不幼稚。但你說要去廁所，卻自己跑到別的地方，大家會擔心，也可能遇到危險。'},{s:'賴安',t:'……我知道了。下次我會先講。'},{t:'你這才發現：他確實說了謊，但「說謊」並不能解釋整件事，更不能直接證明腳印是他的。'}],()=>{state.clues.add('truth');updateCount();finalReflection()})}
function finalReflection(){choose('回頭看早上的事情，你現在會怎麼記下賴安？',[{label:'他就是一個會說謊、亂跑的孩子',value:'label'},{label:'他確實做錯事，但還需要理解他為什麼不敢說實話',value:'half'},{label:'既然是看獨角仙，就不需要提醒他安全問題',value:'excuse'}],v=>{track('laian_reflection',{choice:v});const feedback=v==='half'?'行為需要被處理，但一個行為並不足以定義整個孩子。':v==='label'?'這個判斷只看見他的行為，還沒有看見他不敢說出口的原因。':'理解他的原因，不代表忽略離隊帶來的安全風險。';say([{t:feedback},{t:'15:00，第一天的活動結束，孩子們背起書包準備賦歸。'}],()=>showScene('dismissal'))})}
function drawingPuzzle(){say([{s:'你',t:'芮琪，妳在畫今天的活動嗎？',img:'day2-richi-drawing-consistent.webp'},{s:'芮琪',t:'不完全是。我每週上畫畫課，媽媽也會準備畫本。'},{s:'你',t:'我可以看看這張嗎？'},{t:'她把速寫本轉向你。畫上是幾個牽手的孩子。'},{t:'仔細看看，哪裡和現在的第三小隊對不上？',img:'day2-richi-reveal-consistent.webp'}],()=>showScene('day2drawingReveal'))}
function alanConversation(){say([{s:'你',t:'等等，你是……',img:'day2-alan-hidden.webp'},{t:'男孩先往後退了一步。這時連恩、賴安、洛祈和芮琪也從教室方向跑了過來。',img:'day2-alan-talk.webp'},{s:'連恩',t:'隊輔老師，他是阿龍！以前我們五個都在同一隊。'},{s:'賴安',t:'我昨天有看到他。我怕說了以後，你們就不讓他再過來。'},{s:'洛祈',t:'我們只是想跟他聊一下今天玩了什麼。'},{s:'芮琪',t:'他不是陌生人。畫裡第五個人就是他。'},{s:'阿龍',t:'對不起，我沒有要弄壞東西。我只是想來看看他們。'},{s:'你',t:'你以前也參加過營隊？'},{s:'阿龍',t:'嗯，去年我們五個同隊。後來家裡發生了一些事，很多原本可以做的事情都得先停下來，今年就沒有報名。'},{s:'阿龍',t:'其實我剛剛一直在想……明天是最後一天，我也想跟大家一起參加一下。'},{s:'阿龍',t:'不用很久，能跟他們一起玩一會兒就好了。'},{t:'你一時說不出「好」或「不行」。'}],openDayTwoDirectorLine)}
function openDayTwoDirectorLine(){hideAll();$('#phone').classList.remove('hidden');state.phoneMode='day2';state.phoneView='chat';$('#phoneTitle').textContent='營隊主任';const m=$('#messages');m.innerHTML='<div class="msg"><div class="avatar">主任</div><div class="bubble">下午的活動還順利嗎？</div></div><button class="send-report" id="askAlan">詢問阿龍能否參加最後一天</button>';$('#askAlan').onclick=()=>{m.innerHTML+='<div class="msg me"><div class="bubble">主任，我們找到之前留下腳印的孩子了。他叫阿龍，是四個孩子以前的朋友。他想參加明天最後一天，可以嗎？</div></div>';const replies=['我知道這個孩子，但他不在這次營隊名單裡，餐點、材料和保險資料都沒有登記。','如果要補登最後一天，家長必須在今天下班前親自來學校填同意書，也要確認健康資料和接送人。','他的媽媽可能不方便特地跑一趟。你們先把孩子能來的時間問清楚；若方案排得出來，我再陪你們向家長說明。'];let i=0;const add=()=>{if(i===replies.length){const b=document.createElement('button');b.className='send-report';b.textContent='收起手機，詢問阿龍';b.onclick=alanLimits;m.append(b);return}setTimeout(()=>{m.innerHTML+=`<div class="msg"><div class="avatar">主任</div><div class="bubble">${replies[i++]}</div></div>`;m.scrollTop=m.scrollHeight;add()},430)};add()}}
function alanLimits(){hideAll();photo.style.backgroundImage='url("day2-alan-talk.webp")';say([{s:'你',t:'主任說，媽媽今天下班前要到校補資料。你明天什麼時候能來？'},{s:'阿龍',t:'早上要顧弟弟，媽媽中午能載我來，大概十一點到一點。但她下班很累，還要接弟弟，不一定願意再跑學校。'},{s:'你',t:'我們先排清楚時間、餐點和照顧方式，再和主任一起向媽媽說明。你沒有過敏，材料也能和大家共用，對嗎？'},{s:'阿龍',t:'對。'},{t:'16:20，教室只剩你和艾莉。桌上是阿龍遇到的四個問題，以及主任能提供的時間、備用金與隊輔空檔。',img:'day2-planning-table.webp'}],startPlanner)}
