function playClosingReflection(){say([{t:'13:00，接送時間到了。五個孩子背起書包，拿著剛完成的作品走到穿堂；阿龍的媽媽也剛好趕到。',img:'day3-pickup-consistent.webp'},{t:'你向媽媽確認接送資料，阿龍已經迫不及待地把作品舉到她面前。'},{s:'阿龍媽媽',t:'我們家最近的工作和收入都不太穩定，我只好多排一些班。阿龍放學後常要幫忙顧弟弟，我也沒有辦法每天接送他。'},{s:'阿龍媽媽',t:'營隊的費用、交通和時間一起碰上，我們就很難排出能配合的方法。昨天你們把安排說清楚，我才知道今天還有辦法讓他來。謝謝你們。'},{t:'鐘聲響起。五個孩子一邊約下次見，一邊走向各自的接送人。阿龍走了幾步，又回頭朝你和艾莉揮了揮手。'},{s:'你',t:'我只是多問了一句，再重新安排時間和需要的東西，阿龍今天就多了一個能參與的位置。'},{t:'你無法一次改變所有條件，但可以先看見限制，從自己做得到的一步開始。'}],showRoleResult)}
function showRoleResult(){const order=['story','resource','support','cross'],max=Math.max(...order.map(k=>state.scores[k])),tied=order.filter(k=>state.scores[k]===max);let key=tied[0];for(const d of [...state.decisions].reverse()){const found=d.roles.find(k=>tied.includes(k));if(found){key=found;break}}const r=roleProfiles[key],o=outcomeProfiles[state.outcome];completeDay(3,{outcome:state.outcome});track('game_completed',{outcome:state.outcome,total_duration_seconds:elapsedSeconds(state.gameStartedAt)});track('persona_result',{persona:key,persona_name:r.name});const actions=r.actions.map((x,i)=>`<article class="action-mission ${i===0?'featured':''}"><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p><div><button class="commit-action" data-action="${i}">選這一步</button></div></article>`).join('');hideAll();$('#hud').classList.add('hidden');photo.style.backgroundImage=`url("${o.img}")`;$('#result').style.setProperty('--role',r.color);$('#result').classList.remove('hidden');$('#resultContent').innerHTML=`<section class="role-hero"><div class="role-icon">${r.icon}</div><p class="eyebrow">你的行動者傾向</p><h2>${r.name}</h2><p>${r.fit}</p></section><section class="result-summary"><h3>你的分析結果</h3><p><b>你擅長的方式：</b>${r.strength}</p><p><b>行動時可以留意：</b>${r.blind}</p><p>${o.impact}</p></section><section class="action-zone"><p class="action-kicker">從一件做得到的小事開始</p><h2>你現在可以這樣做</h2>${actions}<div id="commitment" class="commitment hidden"></div></section><section class="confidence-check"><p class="action-kicker">最後一個問題</p><h3>玩完故事後，你覺得自己能為教育議題做出一點改變嗎？</h3><div><button data-confidence="know_first_step">我已經知道可以從哪一步開始</button><button data-confidence="learn_more">我願意再了解更多</button><button data-confidence="still_unsure">我仍不確定自己能做什麼</button></div><p id="confidenceFeedback" class="hidden">謝謝你的回答，我們會用這份匿名回饋改善遊戲。</p></section><button id="resultThanks">看完結果，繼續</button><button id="resultHome" class="secondary-result">回到三日營隊紀錄</button>`;$$('.commit-action').forEach(b=>b.onclick=()=>selectImmediateAction(r,Number(b.dataset.action)));$$('[data-confidence]').forEach(b=>b.onclick=()=>selectConfidence(b.dataset.confidence));$('#resultThanks').onclick=showThanks;$('#resultHome').onclick=()=>page('chapters')}
function selectConfidence(answer){track('action_confidence',{answer});$$('[data-confidence]').forEach(b=>{b.disabled=true;b.classList.toggle('selected',b.dataset.confidence===answer)});$('#confidenceFeedback').classList.remove('hidden')}
function selectImmediateAction(role,index){track('action_selected',{persona:role.name,action_index:index});const a=role.actions[index],box=$('#commitment');localStorage.setItem('clockActionCommitment',JSON.stringify({role:role.name,action:a[1],createdAt:new Date().toISOString()}));box.classList.remove('hidden');box.innerHTML=`<b>✓ 你的第一步已經選好了</b><p>${a[0]}｜${a[1]}</p><small>不用一次改變整個世界。先完成這一小步，就已經從「在意」走向「參與」。</small><a id="actionLink" target="_blank" rel="noopener" href="${a[4]}">${a[3]} ↗</a>`;$('#actionLink').onclick=()=>track('action_link_clicked',{persona:role.name,action_index:index});box.scrollIntoView({behavior:'smooth',block:'center'})}
