$('#acceptFlyer').onclick=()=>{hideAll();photo.style.backgroundImage='url("prologue-chat.webp")';say([{s:'艾莉',t:'暑假才第三天，我已經快無聊死了。'},{s:'你',t:'剛剛不是還說想找事情做、順便賺點錢？'},{s:'艾莉',t:'對啊。這個有小朋友、有活動，還有一點隊輔津貼，感覺比在家發霉好吧？'},{t:'你又看了一次招募單：活動共三天，由大專生擔任小隊隊輔。'}],confirmFlyer)};$('#flyerBack').onclick=()=>page('prologue');
$('#dayOne').onclick=()=>{state.gameStartedAt=Date.now();localStorage.setItem('clockGameStartedAt',String(state.gameStartedAt));startDay(1);state.clues.clear();state.children.clear();state.clay.clear();state.briefRead=false;state.reported=false;state.rearIntroSeen=false;state.phoneMode='brief';state.phoneView='home';updateCount();resetSceneHistory();photo.style.backgroundImage='url("hexing-campus.webp")';hideAll();say([{t:'營隊前一天，你和艾莉已經完成場勘，並親手鎖好後棟側門。'},{t:'第一天，07:30。你們提早回到合興國小。'},{t:'穿堂還很安靜，背包裡忽然傳來手機震動。'}],()=>showScene('campus'))};
$('#dayTwo').onclick=()=>{startDay(2);state.d2clues.clear();state.d2talk.clear();state.decisions=[];localStorage.removeItem('clockSavedPlan');updateCount();resetSceneHistory();photo.style.backgroundImage='url("day2-rear-v2.webp")';hideAll();say([{t:'第二天，07:50。你和艾莉再次來到後棟。',img:'day2-rear-v2.webp'},{s:'艾莉',t:'側門重新鎖好了，總務也貼了告示。'},{t:'正要離開時，你們發現花圃泥地多了一串新腳印。'}],()=>showScene('day2rear'))};
$('#dayThree').onclick=()=>{const saved=localStorage.getItem('clockSavedPlan');if(saved){const data=JSON.parse(saved);state.decisions=data.decisions;state.resources=data.resources;state.scores=data.scores}else if(state.decisions.length!==4){toast('先完成第二天的方案規劃。');return}startDay(3);state.gameStartedAt=Number(localStorage.getItem('clockGameStartedAt'))||state.gameStartedAt||Date.now();resetSceneHistory();markCheckpoint('along_arrived');playDayThreeOutcome()};
$('#plannerBack').onclick=()=>page('chapters');
$('#bagBtn').onclick=openBag;$('#bagBack').onclick=()=>showScene('campus');$('#bagPhone').onclick=()=>openPhone('brief');$('#bagMap').onclick=()=>openDocument('map','bag');$('#docBack').onclick=()=>state.docSource==='phone'?openPhone(state.phoneMode):openBag();
function returnFromClue(){showScene(state.phase)}
$('#clueBack').addEventListener('click',returnFromClue);$('#clueReturnBottom').addEventListener('click',returnFromClue);
$('#sceneNext').onclick=()=>{if(state.phase==='team')afterChildren();else if(state.phase==='rear')concernReport();else if(state.phase==='compare')shoePuzzle();else if(state.phase==='day2map')say([{t:'大家重新確認方向後，沿著二樓穿堂找到第二張提示：下一關藏在老榕樹附近。'},{t:'洛祈一看到榕樹就衝到最前面。',img:'day2-explore-tree-v2.webp'},{s:'賴安',t:'等一下啦，大家要一起走！'},{s:'連恩',t:'芮琪，妳幫我們記答案，我去把洛祈叫回來。'},{t:'同一件事裡，每個孩子都用了不同的方法參與。'}],()=>showScene('day2tree'));else if(state.phase==='day2tree'){state.d2clues.add('d2map');updateCount();say([{t:'10:20，校園大探索順利完成。四個孩子靠著不同的方法，拼出了最後一題。'},{s:'艾莉',t:'如果只看誰最快找到答案，會漏掉很多人的功勞耶。'},{s:'你',t:'有人找方向、有人顧隊伍、有人試新的路、也有人把線索記下來。少一個都不行。'},{t:'11:00，水球活動結束。孩子們一身濕，在榕樹下擦頭髮、喝水。芮琪坐在稍遠的樹蔭裡，安靜地畫著畫。',img:'day2-richi-drawing-consistent.webp'}],()=>showScene('day2drawing'))}else if(state.phase==='day2plantkids')say([{t:'孩子們沿著花圃繼續往前調查。你落在隊伍後方，想起早上腳印旁那幾顆黑色種子。',img:'day2-plant-kids-v2.webp'},{t:'13:35，你拿出手機，打開早上拍下的照片，再抬頭比對眼前分散在不同角落的植物。',img:'day2-plant-puzzle-consistent.webp'},{s:'你',t:'如果能找到同一種植物，也許就能知道留下腳印的人是從哪條路過來的。'}],()=>showScene('day2plants'))};
$('#phoneBack').onclick=()=>{if(state.phoneMode==='day2'){alanLimits();return}if(state.phoneView==='chat'){renderContacts();return}if(state.phoneView==='list'){renderPhoneHome();return}if(state.phoneMode==='brief')openBag();else showScene('rear')};
$('#notesBtn').onclick=renderNotes;$('#closeNotes').onclick=()=>$('#notebook').classList.add('hidden');
$('#sceneBack').onclick=()=>{if(sceneHistoryIndex>0){sceneHistoryIndex--;showScene(sceneHistory[sceneHistoryIndex],false)}else page('chapters')};
$('#sceneForward').onclick=()=>{if(sceneHistoryIndex<sceneHistory.length-1){sceneHistoryIndex++;showScene(sceneHistory[sceneHistoryIndex],false)}};
$('#replay').onclick=()=>page('chapters');
$('#finishDayTwo').onclick=()=>page('chapters');
$('#nextDayTwo').onclick=()=>$('#dayTwo').click();
$('#nextDayThree').onclick=()=>$('#dayThree').click();
$('#thanksHome').onclick=()=>page('chapters');
$('#resultBack').onclick=()=>page('chapters');
$('#thanksBack').onclick=()=>page('postSurvey');
const consentPanel=$('#analyticsConsent'),consentStatus=localStorage.getItem('clockAnalyticsConsent');
if(consentStatus==='accepted'){window.posthog?.opt_in_capturing?.()}else if(consentStatus==='declined'){window.posthog?.opt_out_capturing?.()}else{consentPanel.classList.remove('hidden')}
$('#analyticsAccept').onclick=()=>{localStorage.setItem('clockAnalyticsConsent','accepted');window.posthog?.opt_in_capturing?.();consentPanel.classList.add('hidden');window.posthog?.capture?.('analytics_consent',{choice:'accepted',game_version:analyticsVersion});window.posthog?.capture?.('$pageview')};
$('#analyticsDecline').onclick=()=>{localStorage.setItem('clockAnalyticsConsent','declined');window.posthog?.opt_out_capturing?.();consentPanel.classList.add('hidden')};
